type Section = { title: string; body?: string; bullets?: string[] };

const sections: Record<'en' | 'id', Section[]> = {
  en: [
    { title: '1. Acceptance and scope', body: 'These Terms of Service (“Terms”) govern your use of kapitech.id and the website-related services made available by PT Kapitech Digital Indonesia (“Kapitech”, “we”, “us”, or “our”). By accessing the website, requesting a service, submitting information for a business engagement, or entering an engagement that expressly references these Terms, you acknowledge and agree to them to the extent they apply.\n\nA signed agreement, proposal, statement of work (“SOW”), order form, quotation, service agreement, NDA, or other written project contract may contain more specific rules. If a project-specific document conflicts with these general website Terms, the project-specific document controls for that engagement.' },
    { title: '2. Definitions', body: '“Website” means kapitech.id and its public pages, forms, editorial content, media, and related website functionality. “Services” means the professional services described in a project proposal, SOW, or other written agreement. “Deliverables” means the agreed outputs to be produced for a client. “Client” means the person or organisation purchasing or engaging Kapitech for Services.\n\nA quotation, estimate, portfolio example, article, or general service description is not automatically a binding commitment to deliver an identical result. Binding scope, price, milestones, acceptance criteria, and responsibilities should be read from the document that forms the specific engagement.' },
    { title: '3. About Kapitech', body: 'Kapitech is a digital agency based in Indonesia. Our capabilities may include website design and development, UI/UX and product design, branding and identity, visual design, motion graphics and video, e-commerce, digital product development, integrations, maintenance, and related creative or technology services.\n\nServices are delivered according to the team, technology, scope, assumptions, and commercial terms available for the particular project. The website may describe capabilities at a high level, but a client should rely on the written project scope for the exact deliverables that are included.' },
    { title: '4. Website access and lawful use', bullets: [
      'Use the website for lawful purposes and in a manner consistent with these Terms.',
      'Do not interfere with website availability, security, infrastructure, or other users’ access.',
      'Do not attempt to bypass authentication, obtain unauthorised access, inspect private systems, or access source code or endpoints that are not intentionally public.',
      'Do not introduce malware, ransomware, exploit payloads, malicious scripts, excessive automated requests, or other harmful traffic.',
      'Do not impersonate another person or organisation or submit information that you do not have the right to provide.',
      'Do not use website content or systems to facilitate unlawful activity, fraud, harassment, abuse, or infringement of third-party rights.'
    ]},
    { title: '5. Website content and informational material', body: 'Articles, guides, case studies, visual examples, service descriptions, diagrams, and other public content are provided primarily for informational and commercial communication purposes. They may describe general approaches rather than a guaranteed project plan for every client.\n\nTechnology, pricing, availability, product interfaces, regulations, provider terms, and best practices can change. Content that was accurate when published may later require an update. Clients should request current project-specific information before relying on an article, case study, benchmark, or general service statement for a commercial decision.' },
    { title: '6. Proposals, discovery, and project formation', body: 'A project normally begins with a discovery or briefing process followed by a proposal, quotation, SOW, order form, or contract. These documents may define objectives, scope, deliverables, design or revision rounds, milestones, dependencies, technologies, content requirements, client responsibilities, fees, taxes, payment schedules, acceptance criteria, and support terms.\n\nNo project feature, page, integration, or business outcome is considered included merely because it appears on Kapitech’s website or was discussed informally. The written project scope is the source of truth for the engagement.' },
    { title: '7. Scope and deliverables', body: 'The scope should describe what Kapitech will produce and any assumptions that make the scope possible. Examples include page counts, screen counts, design rounds, integrations, supported environments, content responsibilities, technical modules, documentation, and launch support.\n\nItems that are technically related to the project but not expressly included are not automatically part of the scope. Where a requirement is ambiguous, Kapitech may ask for clarification before committing to a delivery or may document an assumption in the proposal or SOW.' },
    { title: '8. Changes and change requests', bullets: [
      'A material change to approved requirements, functionality, integrations, content, design direction, technology, or timeline may require a change request.',
      'A change request may affect fees, schedule, staffing, testing, third-party costs, or acceptance criteria.',
      'Additional work should not be started on the assumption that the original fee will automatically cover it unless that inclusion is confirmed.',
      'Small clarifications that do not materially change scope may be handled within the agreed delivery process.',
      'The applicable SOW or written change approval determines the final treatment of a requested change.'
    ]},
    { title: '9. Client responsibilities', bullets: [
      'Provide accurate requirements, content, assets, access, credentials, technical information, and approvals that are reasonably required for the project.',
      'Respond to questions and review requests within the agreed working process.',
      'Ensure that supplied text, images, software, fonts, trademarks, data, documents, and other materials may legally be used.',
      'Provide a person authorised to give consolidated feedback and approvals when required.',
      'Maintain responsibility for the accuracy and legality of information that the client asks Kapitech to publish or implement.',
      'Pay invoices and other agreed charges according to the project schedule.'
    ]},
    { title: '10. Client materials and rights', body: 'The client remains responsible for materials it supplies or directs Kapitech to use, including logos, images, copy, datasets, code, documents, fonts, videos, credentials, and third-party services. The client represents that it has the necessary rights, permissions, licences, consents, and authority to provide those materials and authorise their use for the project.\n\nKapitech may refuse, replace, isolate, or remove a material where there is a reasonable legal, licensing, security, privacy, or rights concern. Such a request may affect schedule or scope where the replacement requires additional work.' },
    { title: '11. Estimates, budgets, and commercial assumptions', body: 'Unless expressly stated otherwise, pre-contract budgets and estimates are indicative. A budget may depend on assumptions about page count, content readiness, third-party fees, technical access, revision rounds, integrations, performance requirements, and delivery dates.\n\nIf assumptions change materially, the final price or schedule may change. Kapitech will seek to make material commercial assumptions clear in the relevant proposal or SOW rather than relying on the website to define a fixed price.' },
    { title: '12. Fees, invoices, taxes, and expenses', bullets: [
      'Project fees, deposits, milestone payments, currency, taxes, and due dates are defined by the applicable proposal, SOW, invoice, or contract.',
      'Third-party costs such as domains, hosting, paid plugins, software licences, stock assets, API usage, payment gateways, or external platforms may be separate unless expressly included.',
      'Bank charges, payment-provider charges, withholding taxes, and other transaction costs are handled according to the applicable contract and law.',
      'An invoice remains payable according to its agreed due date even if the client is internally changing priorities, unless the contract provides otherwise.',
      'Overdue payment may result in work being paused, delivery being rescheduled, access being restricted, or other contractual remedies after reasonable notice.'
    ]},
    { title: '13. Taxes and statutory charges', body: 'Applicable taxes and statutory charges are handled according to the project contract and Indonesian law or other law that properly applies to the transaction. A quoted amount should be read together with any stated tax treatment.\n\nWhere a client is required to withhold tax, issue a withholding certificate, or provide other statutory documentation, the parties should follow the applicable contractual process so that payment records can be reconciled correctly.' },
    { title: '14. Timelines, dependencies, and delivery', body: 'Project schedules depend on client inputs, approvals, third-party availability, content readiness, access to systems, technical feasibility, and the assumptions recorded in the SOW. A timeline is therefore not independent of client and third-party dependencies.\n\nIf a dependency is delayed or a requirement changes, the parties may need to revise milestones. Kapitech will make reasonable efforts to communicate material risks, blockers, and schedule impacts once they are known.' },
    { title: '15. Review, revisions, and approval', body: 'Where a project includes design or review rounds, feedback should be consolidated and submitted through the agreed communication channel. A requested revision should normally relate to the approved requirements, design direction, or acceptance criteria.\n\nA deliverable is not automatically defective because the client later changes strategic direction, introduces a new requirement, or prefers a different style after approval. New requirements may be treated as change requests depending on the contract.' },
    { title: '16. Acceptance and launch', body: 'Acceptance criteria may be defined for specific deliverables, milestones, QA stages, or launch readiness. Acceptance may require review of functionality against the agreed requirements, not a guarantee that every possible future use case has been tested.\n\nIf a project is launched with known minor issues that do not prevent the agreed use, the parties may record them as post-launch items rather than treating the entire delivery as rejected. The specific treatment is determined by the applicable SOW or service agreement.' },
    { title: '17. Intellectual property ownership and licence', body: 'Ownership and licensing of deliverables are determined by the applicable written agreement. Where the agreement provides for transfer or exclusive client rights, the transfer takes effect according to the conditions stated in that agreement, including any required payment.\n\nPre-existing Kapitech materials, general methods, reusable components, frameworks, libraries, templates, internal tools, know-how, design patterns, and generic utilities remain with Kapitech unless expressly assigned. Client rights in custom work do not automatically transfer unrelated pre-existing materials.' },
    { title: '18. Third-party and open-source components', body: 'Projects may incorporate open-source software, frameworks, APIs, fonts, stock assets, plugins, CMS platforms, hosting services, payment services, analytics tools, or other third-party technology. Those components remain subject to their own licences and terms.\n\nKapitech cannot grant ownership or rights that belong to a third party. A project-specific assignment or licence therefore does not remove obligations contained in a third-party licence. Where material licensing constraints are known to affect the intended use, Kapitech may identify them during project planning.' },
    { title: '19. Confidentiality', body: 'Confidential information exchanged during a project may be protected by an NDA or confidentiality provisions in the SOW. Each party should use the other party’s confidential information only for the relevant engagement and should take reasonable measures to prevent unauthorised disclosure.\n\nConfidentiality obligations commonly do not apply to information that is already public without breach, was lawfully known before disclosure, is independently developed without use of confidential information, or must be disclosed by law, subject to the exact wording of the applicable agreement.' },
    { title: '20. Privacy and Personal Data', body: 'Personal Data submitted to the public website is governed by Kapitech’s Privacy Policy and Cookie Policy. Data processed within a client project may require additional contractual controls, including a data-processing agreement, security schedule, access restrictions, retention rules, or incident procedures.\n\nEach party should use appropriate safeguards for the systems and data it controls. The parties should not assume that a public website privacy notice replaces a project-specific data-processing or security agreement where one is required.' },
    { title: '21. Security responsibilities', body: 'Security responsibilities depend on the system and party controlling it. Kapitech is responsible for the reasonable security practices applicable to the services and infrastructure under its control. A client remains responsible for the security of its own accounts, credentials, internal devices, business processes, and third-party services under its control.\n\nClients should not share master passwords or unrestricted credentials through ordinary chat or email if a safer method is available. Where secure access is required, the project team should use the access mechanism agreed for the project.' },
    { title: '22. Third-party platforms and service availability', body: 'A project may depend on hosting companies, cloud platforms, payment gateways, APIs, domain registrars, CMS vendors, app stores, email providers, analytics platforms, maps, identity providers, or other external systems. Those providers can change their APIs, pricing, terms, rate limits, security policies, features, or availability without Kapitech’s control.\n\nKapitech will not be treated as the guarantor of uninterrupted third-party availability unless a specific written agreement expressly assigns such an obligation and defines its limits.' },
    { title: '23. Warranty, bug fixes, and support', body: 'Any warranty period, defect remediation, bug-fix window, maintenance plan, monitoring, SLA, response time, security patching, or post-launch support package must be defined in the applicable SOW or service agreement. This website does not create a universal warranty period.\n\nA bug generally means a material failure to perform an agreed requirement. A new feature, new page, new integration, major copy change, redesign request, or changed business requirement is normally additional work unless the contract states otherwise.' },
    { title: '24. No guarantee of business outcomes', body: 'Kapitech can provide professional design, engineering, branding, and digital services, but many commercial outcomes depend on factors outside our control. Unless expressly guaranteed in a signed agreement, we do not promise specific revenue, lead volume, conversion rate, search ranking, investment, user growth, market adoption, or other business performance.\n\nCase studies and examples are evidence of particular work rather than a promise that another client will obtain the same outcome. Results can differ because of market conditions, budgets, product quality, pricing, content, distribution, competition, and client execution.' },
    { title: '25. Portfolio, case studies, and public references', body: 'Kapitech may want to show completed work in a portfolio, case study, presentation, award submission, or other marketing material. Client-specific rights should follow the SOW, NDA, or written approval.\n\nWe should not intentionally reveal confidential data, private credentials, unpublished business plans, protected source material, or other information where publication would violate a confidentiality or contractual obligation. If publication rights are restricted, the restriction controls how the work is presented.' },
    { title: '26. Suspension of work', body: 'Kapitech may pause work where permitted by the applicable contract. Grounds can include overdue invoices, missing client inputs, prolonged inactivity, security concerns, unlawful requests, repeated scope changes without approval, or other material issues that prevent reasonable delivery.\n\nWhere practical, we will communicate the reason for a pause and what is required to resume. A pause may affect delivery dates, team allocation, third-party costs, or availability of the originally planned schedule.' },
    { title: '27. Termination', body: 'Termination rights and consequences should be defined in the applicable project agreement. Depending on the contract, termination may require payment for completed work, committed third-party costs, approved expenses, or cancellation charges.\n\nOn termination, provisions concerning payment, intellectual property, confidentiality, Personal Data, licences, dispute resolution, liability, and other obligations that by their nature should continue may survive the end of the engagement.' },
    { title: '28. Indemnity and third-party claims', body: 'Where permitted by applicable law and subject to the project agreement, each party is responsible for claims arising from its own unlawful conduct, material breach, or infringement caused by materials, instructions, or systems under its control.\n\nClient-specific indemnities should be stated expressly in the written contract rather than inferred from this website. Nothing in these Terms is intended to remove rights or liabilities that cannot legally be excluded.' },
    { title: '29. Limitation of liability', body: 'To the maximum extent permitted by applicable law, and subject to mandatory legal rights, Kapitech is not responsible for indirect, incidental, special, consequential, or punitive losses, or for loss of profits, goodwill, business opportunities, anticipated savings, or data, except to the extent such limitation is prohibited by law or modified by the applicable written agreement.\n\nAny contractual liability cap should be read from the project agreement. If there is no agreed cap, liability is limited to the extent permitted by applicable law and the facts of the relevant claim.' },
    { title: '30. Force majeure', body: 'Neither party is responsible for delay or failure caused by circumstances beyond its reasonable control, such as natural disasters, widespread infrastructure outages, war, civil unrest, government restrictions, major cybersecurity events affecting critical infrastructure, or significant third-party failures.\n\nThe affected party should take reasonable steps to mitigate the impact and resume performance as soon as reasonably possible. Force majeure does not automatically remove payment obligations for work already performed or expenses already incurred unless the applicable agreement states otherwise.' },
    { title: '31. Governing law and dispute resolution', body: 'These general Terms are governed by the laws of the Republic of Indonesia unless a project-specific written agreement states another governing law. The parties should first attempt to resolve disputes through good-faith discussion and exchange of relevant information.\n\nIf negotiation does not resolve a material dispute, the parties should follow the forum, jurisdiction, arbitration clause, escalation process, or other dispute mechanism stated in the applicable contract. Where no project-specific mechanism exists, the parties may seek remedies available under applicable Indonesian law.' },
    { title: '32. Changes to these Terms', body: 'Kapitech may update these website Terms when the website, services, legal requirements, or business practices change. The latest general version will be posted on this page with an updated date.\n\nUpdating these website Terms does not by itself amend an already signed client contract. Existing projects remain governed by the contract and amendment procedure applicable to them unless the contract expressly incorporates future versions of these website Terms.' },
    { title: '33. Contact', body: 'PT Kapitech Digital Indonesia\nLinea Residence, Block G No. 5, Jl. Melati Loka, Paku Jaya, Serpong Utara, Kota Tangerang Selatan, Banten 15220, Indonesia\nEmail: hello@kapitech.id\nPhone / WhatsApp: +62 877-6995-7062' }
  ],
  id: [
    { title: '1. Penerimaan dan ruang lingkup', body: 'Syarat Layanan (“Syarat”) ini mengatur penggunaan kapitech.id dan layanan terkait website yang disediakan PT Kapitech Digital Indonesia (“Kapitech”, “kami”). Dengan mengakses website, meminta layanan, mengirim informasi untuk kebutuhan bisnis, atau masuk ke dalam engagement yang secara tegas merujuk pada Syarat ini, Anda menyetujui ketentuan yang berlaku.\n\nProposal, statement of work (“SOW”), order form, quotation, service agreement, NDA, atau kontrak tertulis lain dapat memuat aturan yang lebih spesifik. Jika dokumen proyek bertentangan dengan Syarat umum ini, dokumen proyek yang berlaku mengendalikan engagement tersebut.' },
    { title: '2. Definisi', body: '“Website” berarti kapitech.id beserta halaman publik, formulir, konten editorial, media, dan fungsi terkait. “Layanan” berarti jasa profesional yang dijelaskan dalam proposal, SOW, atau perjanjian tertulis. “Deliverables” berarti hasil kerja yang disepakati. “Klien” berarti orang atau organisasi yang membeli atau menggunakan Layanan Kapitech.\n\nQuotation, estimasi, contoh portfolio, artikel, atau deskripsi layanan umum tidak otomatis menjadi janji kontraktual untuk menghasilkan hasil yang sama. Scope, harga, milestone, acceptance criteria, dan tanggung jawab yang mengikat harus dilihat pada dokumen yang membentuk engagement.' },
    { title: '3. Tentang Kapitech', body: 'Kapitech adalah digital agency berbasis di Indonesia. Kemampuan kami dapat mencakup website design dan development, UI/UX dan product design, branding dan identity, visual design, motion graphics dan video, e-commerce, digital product development, integrasi, maintenance, dan layanan kreatif maupun teknologi terkait.\n\nLayanan diberikan sesuai tim, teknologi, scope, asumsi, dan ketentuan komersial yang tersedia untuk proyek tertentu. Website dapat menjelaskan kemampuan secara umum, tetapi deliverables pasti ditentukan oleh scope proyek tertulis.' },
    { title: '4. Akses dan penggunaan website', bullets: [
      'Gunakan website hanya untuk tujuan yang sah dan sesuai dengan Syarat ini.',
      'Jangan mengganggu availability, security, infrastructure, atau akses pengguna lain.',
      'Jangan mencoba melewati authentication, mendapatkan akses tidak sah, memeriksa sistem privat, atau mengakses source code atau endpoint yang tidak sengaja dibuat publik.',
      'Jangan memasukkan malware, ransomware, exploit payload, malicious script, automated request berlebihan, atau traffic berbahaya lainnya.',
      'Jangan menyamar sebagai pihak lain atau mengirimkan informasi yang tidak berhak Anda berikan.',
      'Jangan menggunakan website untuk memfasilitasi kegiatan melawan hukum, fraud, harassment, abuse, atau pelanggaran hak pihak ketiga.'
    ]},
    { title: '5. Konten website dan informasi umum', body: 'Artikel, panduan, case study, contoh visual, deskripsi layanan, diagram, dan konten publik lain terutama diberikan untuk kebutuhan informasi dan komunikasi bisnis. Konten dapat menjelaskan pendekatan umum dan tidak otomatis menjadi rencana proyek yang dijamin untuk setiap klien.\n\nTeknologi, harga, availability, interface produk, regulasi, ketentuan provider, dan best practice dapat berubah. Konten yang benar saat dipublikasikan dapat membutuhkan update. Untuk keputusan komersial, klien sebaiknya meminta informasi yang benar-benar terbaru dan relevan dengan proyeknya.' },
    { title: '6. Proposal, discovery, dan pembentukan proyek', body: 'Proyek umumnya dimulai melalui discovery atau briefing, lalu proposal, quotation, SOW, order form, atau kontrak. Dokumen tersebut dapat menjelaskan tujuan, scope, deliverables, design atau revision round, milestone, dependensi, teknologi, kebutuhan konten, tanggung jawab klien, fee, pajak, jadwal pembayaran, acceptance criteria, dan support.\n\nFitur, halaman, integrasi, atau hasil bisnis tidak dianggap termasuk hanya karena muncul di website atau dibicarakan secara informal. Scope tertulis menjadi sumber utama untuk menentukan kewajiban proyek.' },
    { title: '7. Scope dan deliverables', body: 'Scope sebaiknya menjelaskan apa yang akan dibuat Kapitech dan asumsi yang diperlukan. Contohnya dapat mencakup jumlah halaman, jumlah screen, design round, integrasi, environment yang didukung, tanggung jawab konten, modul teknis, dokumentasi, dan launch support.\n\nHal yang masih berhubungan secara teknis tetapi tidak disebut dalam scope tidak otomatis termasuk. Jika requirement belum jelas, Kapitech dapat meminta klarifikasi atau mencatat asumsi sebelum pekerjaan dijalankan.' },
    { title: '8. Perubahan dan change request', bullets: [
      'Perubahan material pada requirement, fungsi, integrasi, konten, arah desain, teknologi, atau timeline dapat memerlukan change request.',
      'Change request dapat memengaruhi biaya, jadwal, staffing, testing, biaya pihak ketiga, atau acceptance criteria.',
      'Pekerjaan tambahan tidak seharusnya dimulai dengan asumsi bahwa fee awal otomatis mencakupnya tanpa konfirmasi.',
      'Klarifikasi kecil yang tidak mengubah scope secara material dapat diproses dalam alur delivery yang sudah disepakati.',
      'SOW atau persetujuan perubahan tertulis menjadi acuan akhir untuk perubahan yang diminta.'
    ]},
    { title: '9. Tanggung jawab klien', bullets: [
      'Memberikan requirement, konten, aset, access, credential, informasi teknis, dan approval yang akurat dan dibutuhkan.',
      'Menjawab pertanyaan dan review request melalui alur kerja yang disepakati.',
      'Memastikan teks, gambar, software, font, trademark, data, dokumen, dan material lain boleh digunakan secara sah.',
      'Menunjuk pihak yang berwenang memberikan feedback dan approval bila dibutuhkan.',
      'Bertanggung jawab terhadap akurasi dan legalitas informasi yang diminta untuk dipublikasikan atau diimplementasikan.',
      'Membayar invoice dan biaya lain sesuai jadwal proyek.'
    ]},
    { title: '10. Material klien dan hak penggunaannya', body: 'Klien bertanggung jawab atas material yang diberikan atau diminta untuk digunakan, termasuk logo, gambar, copy, dataset, kode, dokumen, font, video, credential, dan layanan pihak ketiga. Klien menyatakan bahwa ia memiliki hak, izin, lisensi, consent, dan kewenangan yang diperlukan untuk memberikan material tersebut dan mengizinkan penggunaannya dalam proyek.\n\nKapitech dapat meminta material diganti, dipisahkan, atau dihapus jika terdapat risiko hukum, lisensi, security, privacy, atau hak pihak lain. Jika penggantian membutuhkan pekerjaan tambahan, jadwal atau scope dapat ikut terdampak.' },
    { title: '11. Estimasi, budget, dan asumsi komersial', body: 'Kecuali secara tegas dinyatakan lain, budget dan estimasi sebelum kontrak bersifat indikatif. Estimasi dapat bergantung pada jumlah halaman, kesiapan konten, biaya pihak ketiga, akses teknis, jumlah revision round, integrasi, kebutuhan performa, dan timeline.\n\nJika asumsi berubah secara material, harga atau jadwal dapat berubah. Kapitech berupaya menjelaskan asumsi komersial yang material di proposal atau SOW, bukan menganggap website sebagai daftar harga tetap.' },
    { title: '12. Fee, invoice, pajak, dan biaya', bullets: [
      'Fee proyek, deposit, milestone payment, mata uang, pajak, dan jatuh tempo ditentukan oleh proposal, SOW, invoice, atau kontrak yang berlaku.',
      'Biaya pihak ketiga seperti domain, hosting, plugin berbayar, software licence, stock asset, API, payment gateway, atau platform eksternal dapat ditagihkan terpisah jika tidak termasuk scope.',
      'Biaya bank, payment provider, withholding tax, dan biaya transaksi lainnya mengikuti kontrak dan hukum yang berlaku.',
      'Invoice tetap wajib dibayar sesuai jatuh tempo walaupun prioritas internal klien berubah, kecuali kontrak mengatur lain.',
      'Pembayaran terlambat dapat menyebabkan pekerjaan dihentikan sementara, jadwal diatur ulang, atau remedy kontraktual lain diterapkan setelah pemberitahuan yang wajar.'
    ]},
    { title: '13. Pajak dan kewajiban lainnya', body: 'Pajak dan kewajiban resmi yang berlaku ditangani sesuai kontrak proyek dan hukum Indonesia atau hukum lain yang secara tepat berlaku pada transaksi. Nilai yang ditawarkan harus dibaca bersama informasi mengenai perlakuan pajaknya.\n\nJika klien diwajibkan memotong pajak, menerbitkan bukti potong, atau memberikan dokumen resmi lain, para pihak sebaiknya mengikuti proses kontraktual agar pencatatan pembayaran dapat direkonsiliasi dengan benar.' },
    { title: '14. Timeline, dependensi, dan delivery', body: 'Timeline proyek bergantung pada input klien, approval, availability pihak ketiga, kesiapan konten, akses sistem, kelayakan teknis, dan asumsi dalam SOW. Karena itu timeline tidak berdiri sendiri dari dependensi klien maupun pihak ketiga.\n\nJika dependensi terlambat atau requirement berubah, milestone mungkin perlu direvisi. Kapitech akan berusaha mengomunikasikan blocker, risiko, dan dampak jadwal yang material setelah diketahui.' },
    { title: '15. Review, revisi, dan approval', body: 'Jika proyek memiliki design atau review round, feedback sebaiknya dikonsolidasikan dan dikirim melalui channel yang telah disepakati. Revisi normalnya berkaitan dengan requirement, arah desain, atau acceptance criteria yang telah disetujui.\n\nDeliverable tidak otomatis dianggap cacat karena klien kemudian mengubah strategi, menambah requirement baru, atau menginginkan gaya yang berbeda setelah approval. Requirement baru dapat diperlakukan sebagai change request sesuai kontrak.' },
    { title: '16. Acceptance dan launch', body: 'Acceptance criteria dapat ditentukan untuk deliverable, milestone, QA stage, atau launch readiness. Acceptance biasanya berarti pemeriksaan terhadap requirement yang disepakati, bukan jaminan bahwa semua kemungkinan penggunaan di masa depan telah diuji.\n\nJika proyek diluncurkan dengan isu minor yang tidak mencegah penggunaan sesuai scope, para pihak dapat mencatatnya sebagai post-launch item, bukan otomatis menolak seluruh delivery. Detailnya mengikuti SOW atau service agreement.' },
    { title: '17. Hak kekayaan intelektual dan lisensi', body: 'Kepemilikan dan lisensi deliverables ditentukan oleh perjanjian tertulis yang berlaku. Jika perjanjian menetapkan pengalihan atau hak eksklusif klien, pengalihan berjalan sesuai syarat yang ditentukan, termasuk kewajiban pembayaran bila ada.\n\nMaterial Kapitech yang sudah ada sebelumnya, metode umum, reusable component, framework, library, template, internal tool, know-how, design pattern, dan utility umum tetap menjadi milik Kapitech kecuali dialihkan secara tegas. Hak klien atas custom work tidak otomatis mengalihkan material pre-existing tersebut.' },
    { title: '18. Komponen pihak ketiga dan open-source', body: 'Proyek dapat menggunakan open-source software, framework, API, font, stock asset, plugin, CMS, hosting, payment service, analytics, atau teknologi pihak ketiga lainnya. Komponen tersebut tetap tunduk pada lisensi dan ketentuannya masing-masing.\n\nKapitech tidak dapat memberikan kepemilikan atau hak yang sebenarnya dimiliki pihak ketiga. Assignment atau licence untuk proyek tertentu tidak menghapus kewajiban lisensi pihak ketiga. Jika batasan lisensi diketahui berpengaruh pada penggunaan, Kapitech dapat menjelaskannya selama perencanaan proyek.' },
    { title: '19. Kerahasiaan', body: 'Informasi rahasia yang dipertukarkan selama proyek dapat dilindungi NDA atau klausul kerahasiaan dalam SOW. Masing-masing pihak sebaiknya menggunakan informasi rahasia hanya untuk engagement terkait dan mengambil langkah yang wajar untuk mencegah pengungkapan tanpa izin.\n\nKewajiban kerahasiaan biasanya tidak berlaku pada informasi yang sudah publik tanpa pelanggaran, sudah diketahui secara sah sebelumnya, dikembangkan secara independen tanpa menggunakan informasi rahasia, atau wajib diungkap berdasarkan hukum, dengan mengikuti isi perjanjian yang sebenarnya.' },
    { title: '20. Privasi dan Data Pribadi', body: 'Data Pribadi yang dikirim melalui website publik diatur oleh Privacy Policy dan Cookie Policy Kapitech. Data yang diproses dalam proyek klien dapat membutuhkan kontrol tambahan seperti data-processing agreement, security schedule, pembatasan akses, aturan retensi, atau prosedur insiden.\n\nMasing-masing pihak bertanggung jawab menggunakan safeguards yang sesuai untuk sistem dan data yang berada di bawah kendalinya. Privacy notice website tidak otomatis menggantikan perjanjian pemrosesan data atau security agreement yang secara hukum atau kontrak memang diperlukan.' },
    { title: '21. Tanggung jawab keamanan', body: 'Tanggung jawab keamanan bergantung pada sistem dan pihak yang mengendalikannya. Kapitech bertanggung jawab menerapkan praktik keamanan yang wajar untuk layanan dan infrastruktur yang berada di bawah kendalinya. Klien tetap bertanggung jawab terhadap keamanan akun, credential, perangkat internal, proses bisnis, dan layanan pihak ketiga yang berada di bawah kendali klien.\n\nKlien sebaiknya tidak membagikan master password atau credential penuh melalui chat atau email jika ada metode akses yang lebih aman. Jika akses aman diperlukan, gunakan mekanisme yang disepakati tim proyek.' },
    { title: '22. Platform pihak ketiga dan availability', body: 'Proyek dapat bergantung pada hosting, cloud, payment gateway, API, domain registrar, CMS, app store, email provider, analytics, map service, identity provider, atau sistem eksternal lain. Provider tersebut dapat mengubah API, harga, terms, rate limit, security policy, fitur, atau availability tanpa berada di bawah kendali Kapitech.\n\nKapitech tidak menjadi penjamin uptime pihak ketiga kecuali kewajiban tersebut secara tegas diatur dalam kontrak dan batasannya dijelaskan.' },
    { title: '23. Warranty, bug fix, dan support', body: 'Masa warranty, remediation defect, bug-fix window, maintenance plan, monitoring, SLA, response time, security patch, atau paket post-launch support harus ditentukan dalam SOW atau service agreement. Website ini tidak menciptakan satu masa warranty universal.\n\nBug pada umumnya berarti kegagalan material terhadap requirement yang disepakati. Feature baru, halaman baru, integrasi baru, perubahan copy besar, redesign, atau perubahan kebutuhan bisnis biasanya merupakan pekerjaan tambahan kecuali kontrak menyatakan lain.' },
    { title: '24. Tidak ada jaminan hasil bisnis', body: 'Kapitech dapat menyediakan jasa desain, engineering, branding, dan digital secara profesional, tetapi hasil komersial dipengaruhi banyak faktor di luar kendali kami. Kecuali dijamin secara tegas dalam perjanjian tertulis, kami tidak menjanjikan revenue, jumlah lead, conversion rate, ranking search, investasi, user growth, market adoption, atau hasil bisnis tertentu.\n\nCase study dan contoh portfolio menunjukkan pekerjaan tertentu, bukan janji bahwa klien lain akan memperoleh hasil yang sama. Hasil dapat berbeda karena market, budget, kualitas produk, pricing, content, distribution, competition, dan execution klien.' },
    { title: '25. Portfolio, case study, dan referensi publik', body: 'Kapitech dapat menampilkan pekerjaan yang telah selesai melalui portfolio, case study, presentasi, submission award, atau materi marketing. Hak publikasi harus mengikuti SOW, NDA, atau persetujuan tertulis.\n\nKami tidak seharusnya mengungkap data rahasia, credential, rencana bisnis yang belum dipublikasikan, protected source material, atau informasi lain jika publikasi melanggar kewajiban kerahasiaan atau kontrak. Jika hak publikasi dibatasi, pembatasan tersebut mengendalikan cara pekerjaan ditampilkan.' },
    { title: '26. Penghentian sementara pekerjaan', body: 'Kapitech dapat menghentikan sementara pekerjaan jika diperbolehkan kontrak. Alasannya dapat meliputi invoice jatuh tempo, input klien tidak tersedia, inactivity yang terlalu lama, security concern, permintaan melawan hukum, perubahan scope berulang tanpa approval, atau masalah material lain yang menghalangi delivery.\n\nJika memungkinkan, kami akan menjelaskan alasan pause dan apa yang diperlukan untuk melanjutkan. Pause dapat memengaruhi jadwal, alokasi tim, biaya pihak ketiga, atau ketersediaan slot pengerjaan.' },
    { title: '27. Terminasi', body: 'Hak terminasi dan konsekuensinya harus diatur dalam perjanjian proyek. Tergantung kontrak, terminasi dapat tetap menimbulkan kewajiban membayar pekerjaan yang selesai, biaya pihak ketiga yang sudah terikat, biaya yang telah disetujui, atau cancellation charge.\n\nSetelah terminasi, ketentuan tentang pembayaran, intellectual property, confidentiality, Data Pribadi, lisensi, dispute resolution, liability, dan kewajiban yang secara sifatnya harus tetap berlaku dapat tetap mengikat.' },
    { title: '28. Indemnity dan klaim pihak ketiga', body: 'Sejauh diizinkan hukum dan sesuai perjanjian, masing-masing pihak bertanggung jawab atas klaim yang timbul dari perbuatan melawan hukum, pelanggaran material, atau pelanggaran hak pihak lain yang disebabkan oleh material, instruksi, atau sistem di bawah kendalinya.\n\nKewajiban indemnity khusus klien sebaiknya ditulis secara tegas dalam kontrak, bukan diasumsikan dari website. Tidak ada ketentuan dalam Syarat ini yang dimaksudkan untuk menghilangkan hak atau tanggung jawab yang tidak dapat dikecualikan secara hukum.' },
    { title: '29. Batasan tanggung jawab', body: 'Sejauh diizinkan hukum dan dengan tetap menghormati hak wajib yang tidak dapat dikesampingkan, Kapitech tidak bertanggung jawab atas kerugian tidak langsung, insidental, khusus, konsekuensial, atau punitive, maupun kehilangan profit, goodwill, business opportunity, anticipated savings, atau data, kecuali dibatasi oleh hukum atau diatur berbeda dalam kontrak tertulis yang berlaku.\n\nBatas tanggung jawab kontraktual harus dilihat pada perjanjian proyek. Jika tidak ada batas yang disepakati, tanggung jawab tunduk pada batas yang diperbolehkan hukum dan fakta klaim terkait.' },
    { title: '30. Force majeure', body: 'Masing-masing pihak tidak bertanggung jawab atas keterlambatan atau kegagalan yang disebabkan keadaan di luar kendali wajarnya, seperti bencana alam, gangguan infrastruktur luas, perang, kerusuhan, pembatasan pemerintah, insiden siber besar pada infrastruktur kritis, atau kegagalan signifikan pihak ketiga.\n\nPihak yang terdampak harus mengambil langkah wajar untuk mengurangi dampak dan melanjutkan kinerja sesegera mungkin setelah memungkinkan. Force majeure tidak otomatis menghapus kewajiban pembayaran atas pekerjaan yang telah dilakukan atau biaya yang telah timbul kecuali kontrak menyatakan lain.' },
    { title: '31. Hukum dan penyelesaian sengketa', body: 'Syarat umum ini tunduk pada hukum Republik Indonesia kecuali kontrak proyek menyatakan hukum lain. Para pihak sebaiknya terlebih dahulu berusaha menyelesaikan sengketa melalui pembahasan dengan itikad baik dan pertukaran informasi yang relevan.\n\nJika negosiasi tidak menyelesaikan sengketa material, para pihak mengikuti forum, yurisdiksi, arbitrase, escalation process, atau mekanisme lain yang diatur dalam kontrak. Jika tidak ada mekanisme khusus, para pihak dapat menggunakan upaya hukum yang tersedia berdasarkan hukum Indonesia yang berlaku.' },
    { title: '32. Perubahan Syarat', body: 'Kapitech dapat memperbarui Syarat website ini apabila website, layanan, kebutuhan hukum, atau praktik bisnis berubah. Versi umum terbaru akan dipublikasikan di halaman ini dengan tanggal pembaruan.\n\nPembaruan Syarat website tidak dengan sendirinya mengubah kontrak klien yang telah ditandatangani. Proyek yang sudah berjalan tetap tunduk pada kontrak dan prosedur amendment yang berlaku, kecuali kontrak secara tegas menyatakan sebaliknya.' },
    { title: '33. Kontak', body: 'PT Kapitech Digital Indonesia\nLinea Residence, Blok G No. 5, Jl. Melati Loka, Paku Jaya, Serpong Utara, Kota Tangerang Selatan, Banten 15220, Indonesia\nEmail: hello@kapitech.id\nPhone / WhatsApp: +62 877-6995-7062' }
  ]
};



const supplemental: Record<'en' | 'id', PolicySection[]> = {
  en: [
    { title: '34. Order of precedence between project documents', body: 'A client engagement can contain several documents: proposal, quotation, SOW, order form, change request, NDA, security schedule, invoice, acceptance record, and other written approvals. Not every document has the same purpose. The signed or expressly accepted project agreement should normally be read first for scope, fees, delivery obligations, and commercial terms, while an NDA or security schedule may control confidentiality or security matters.\n\nWhere documents appear inconsistent, the parties should resolve the inconsistency in writing rather than relying on an informal interpretation. These general website Terms are not intended to override a specific signed project agreement.' },
    { title: '35. Discovery information and pre-contract reliance', body: 'Discovery calls, workshops, emails, presentations, moodboards, prototypes, estimates, technical discussions, and other pre-contract materials help the parties understand a project. They do not automatically become binding deliverables or guarantees.\n\nA client should identify material requirements before approval of the SOW. If a requirement is important to the business, it should be documented in the agreed scope, acceptance criteria, or another written project record rather than relying only on a meeting discussion.' },
    { title: '36. Content, approvals, and source-of-truth responsibility', body: 'Clients remain responsible for the factual accuracy of content they provide or ask Kapitech to publish, unless a separate service expressly assigns research or editorial responsibility to Kapitech. This includes company facts, product claims, pricing, legal statements, contact information, regulatory claims, testimonials, and customer-provided statistics.\n\nApproval also matters. When a client approves a design, copy, content set, feature behaviour, or release candidate, the approval becomes an important reference point for determining what was expected at that stage. A later preference change is not necessarily evidence that the approved work was defective.' },
    { title: '37. Third-party credentials and access', body: 'Project delivery may require access to hosting, DNS, CMS, analytics, payment gateways, repositories, domains, cloud environments, advertising accounts, or other systems. Clients should provide the minimum access reasonably needed and should avoid sharing permanent master credentials when a role-based invitation or delegated access is available.\n\nWhen the project ends, access should be reviewed and removed or transferred as appropriate. Kapitech should not be assumed to retain ongoing access after the engagement unless maintenance, support, or another continuing service expressly requires it.' },
    { title: '38. Technical environments and compatibility', body: 'A deliverable can be dependent on specific browsers, devices, operating systems, server versions, APIs, plugins, content-management systems, databases, or third-party infrastructure. The supported environment should be stated in the project scope when compatibility materially affects delivery.\n\nA later change by a platform provider, browser vendor, operating system, plugin, API, hosting environment, or client administrator can create behaviour that did not exist at acceptance. Such changes may require maintenance or additional work rather than constituting an original delivery defect.' },
    { title: '39. Launch, deployment, and rollback', body: 'Launch activities can include deployment, domain configuration, DNS changes, environment configuration, data migration, content publishing, payment testing, analytics validation, and post-launch monitoring. The exact launch plan depends on scope and infrastructure ownership.\n\nWhere a rollback plan is technically appropriate, it should be agreed before launch and should identify the systems, data state, access, decision authority, and conditions for rollback. Not every project can be rolled back without data loss or third-party consequences, so launch risk should be assessed in context.' },
    { title: '40. Maintenance and change in technology', body: 'Post-launch systems may require dependency updates, security patches, content changes, monitoring, backups, performance improvements, bug fixes, and compatibility work. These activities can be included in a maintenance plan or purchased separately.\n\nA maintenance relationship should not be inferred merely because Kapitech originally built a website or application. The applicable agreement determines whether Kapitech is responsible for ongoing maintenance, what systems are covered, response times, exclusions, and commercial terms.' },
    { title: '41. Intellectual property handover and reusable assets', body: 'When a project provides for a client handover, the parties should distinguish client-specific deliverables from reusable agency assets. A handover may include agreed source files, credentials, design files, documentation, deployment instructions, or other materials expressly listed in scope.\n\nKapitech may need to retain generic components, internal tooling, know-how, templates, libraries, or reusable methods so that it can perform work for other clients. A handover should therefore be interpreted according to the agreed rights rather than as an automatic transfer of every underlying tool used to produce the work.' },
    { title: '42. Third-party claims and client instructions', body: 'If a third party claims that client-provided content, trademarks, data, software, imagery, fonts, or instructions infringe its rights, the client may need to help resolve the claim because the material originated from or was directed by the client. Conversely, if a claim arises from a component independently selected and controlled by Kapitech contrary to the agreed scope, the responsibility should be assessed under the project agreement and applicable law.\n\nThe purpose of this distinction is to avoid treating every project issue as automatically belonging to one party without considering who supplied, selected, controlled, or instructed the relevant material.' },
    { title: '43. Suspension for security or unlawful activity', body: 'Kapitech may take reasonable steps to protect systems and people if a project request creates a material security risk, requests unlawful activity, involves unauthorised access, or asks the team to bypass a technical or legal control. Measures can include refusing a particular request, isolating an affected environment, pausing a deployment, requesting safer access, or escalating the issue to the authorised client contact.\n\nSuch a security pause should be distinguished from an ordinary commercial pause. The objective is to reduce immediate risk while preserving a path to resume legitimate work when appropriate.' },
    { title: '44. Disputes about quality, scope, or acceptance', body: 'When the parties disagree about whether work satisfies the contract, the most useful first step is to identify the exact requirement, the accepted reference, the evidence of the delivered behaviour, and the specific gap. General statements that a project “feels wrong” can be valuable feedback, but they are not always sufficient to determine contractual non-conformance.\n\nWhere possible, the parties should separate defects from change requests, new business priorities, content changes, and preference changes. This creates a clearer route to remediation and reduces unnecessary conflict over whether work was within the original scope.' },
    { title: '45. Survivability and records after termination', body: 'Ending a project does not necessarily end every obligation. Provisions concerning unpaid fees, intellectual property rights already granted, confidentiality, Personal Data handling, licences, indemnity, dispute resolution, liability, and records may continue according to their terms or nature.\n\nThe parties should also consider access removal, credential rotation, data return or deletion, source-code handover, domain ownership, hosting control, subscription ownership, and outstanding third-party contracts as part of a responsible close-out.' }
  ],
  id: [
    { title: '34. Urutan kekuatan antara dokumen proyek', body: 'Satu engagement dapat memiliki proposal, quotation, SOW, order form, change request, NDA, security schedule, invoice, acceptance record, dan approval tertulis lainnya. Tidak semua dokumen memiliki fungsi yang sama. Kontrak atau project agreement yang ditandatangani atau diterima secara resmi menjadi rujukan utama untuk scope, fee, delivery, dan ketentuan komersial, sementara NDA atau security schedule dapat lebih khusus untuk confidentiality atau security.\n\nJika terdapat ketidaksesuaian, para pihak sebaiknya menyelesaikannya secara tertulis daripada mengandalkan interpretasi informal. Syarat website ini tidak dimaksudkan untuk mengalahkan kontrak proyek yang telah disepakati.' },
    { title: '35. Informasi discovery dan ketergantungan sebelum kontrak', body: 'Discovery call, workshop, email, presentation, moodboard, estimate, diskusi teknis, prototype, dan materi pra-kontrak membantu memahami proyek. Materi tersebut tidak otomatis menjadi deliverable atau guarantee yang mengikat.\n\nRequirement yang penting bagi bisnis sebaiknya dimasukkan ke scope, acceptance criteria, atau record tertulis lain yang disepakati. Jangan hanya mengandalkan pembahasan meeting untuk requirement yang nantinya menjadi dasar penilaian delivery.' },
    { title: '36. Konten, approval, dan source of truth', body: 'Klien tetap bertanggung jawab atas akurasi konten yang diberikan atau diminta untuk dipublikasikan, kecuali layanan terpisah secara khusus memberikan tanggung jawab research atau editorial kepada Kapitech. Ini termasuk informasi perusahaan, klaim produk, pricing, legal statement, contact, regulatory claim, testimonial, dan statistic yang diberikan klien.\n\nApproval juga penting. Ketika klien menyetujui design, copy, content set, behaviour fitur, atau release candidate, approval menjadi reference penting untuk menentukan ekspektasi saat itu. Perubahan preferensi setelah approval tidak otomatis berarti delivery sebelumnya cacat.' },
    { title: '37. Credential dan akses pihak ketiga', body: 'Delivery dapat membutuhkan akses ke hosting, DNS, CMS, analytics, payment gateway, repository, domain, cloud environment, advertising account, atau sistem lain. Klien sebaiknya memberikan akses minimum yang diperlukan dan menghindari berbagi master credential permanen jika tersedia role-based invitation atau delegated access.\n\nSetelah proyek selesai, akses perlu ditinjau dan dicabut atau dialihkan sesuai kebutuhan. Kapitech tidak otomatis dianggap memiliki akses berkelanjutan setelah engagement selesai kecuali maintenance, support, atau layanan lain memang memerlukan akses tersebut.' },
    { title: '38. Environment teknis dan compatibility', body: 'Deliverable dapat bergantung pada browser, device, operating system, server version, API, plugin, CMS, database, atau infrastructure tertentu. Environment yang didukung sebaiknya ditetapkan dalam scope jika compatibility berpengaruh material.\n\nPerubahan oleh platform provider, browser vendor, operating system, plugin, API, hosting, atau administrator klien dapat menimbulkan behaviour baru setelah acceptance. Perubahan tersebut dapat memerlukan maintenance atau pekerjaan tambahan dan tidak otomatis menjadi defect delivery awal.' },
    { title: '39. Launch, deployment, dan rollback', body: 'Aktivitas launch dapat mencakup deployment, konfigurasi domain, DNS, environment, migrasi data, publishing konten, payment test, analytics validation, dan monitoring pasca-launch. Rencana launch bergantung pada scope dan siapa yang mengendalikan infrastructure.\n\nJika rollback teknis diperlukan, rencana tersebut sebaiknya disepakati sebelum launch dan menetapkan system, data state, access, decision authority, serta kondisi rollback. Tidak semua proyek dapat di-rollback tanpa risiko data loss atau konsekuensi pihak ketiga, sehingga risiko launch harus dinilai sesuai konteks.' },
    { title: '40. Maintenance dan perubahan teknologi', body: 'Sistem setelah launch dapat membutuhkan dependency update, security patch, content change, monitoring, backup, performance improvement, bug fix, dan compatibility work. Aktivitas tersebut dapat termasuk dalam maintenance plan atau dibeli secara terpisah.\n\nHubungan maintenance tidak otomatis ada hanya karena Kapitech pernah membangun website atau application. Agreement menentukan apakah Kapitech bertanggung jawab terhadap maintenance, system yang tercakup, response time, exclusion, dan fee.' },
    { title: '41. Handover intellectual property dan reusable asset', body: 'Jika project menyediakan handover, para pihak perlu membedakan deliverable khusus klien dari asset agency yang reusable. Handover dapat mencakup source file, credential, design file, documentation, deployment instruction, atau material lain yang secara tegas disebutkan.\n\nKapitech dapat tetap memiliki generic component, internal tool, know-how, template, library, atau reusable method agar dapat digunakan pada pekerjaan lain. Handover harus dibaca berdasarkan hak yang disepakati, bukan sebagai pengalihan otomatis semua tools yang digunakan untuk membuat hasil kerja.' },
    { title: '42. Klaim pihak ketiga dan instruksi klien', body: 'Jika pihak ketiga mengklaim bahwa konten, trademark, data, software, imagery, font, atau instruksi yang berasal dari klien melanggar haknya, klien dapat perlu membantu penyelesaian karena material tersebut berasal dari atau diarahkan oleh klien. Sebaliknya, jika klaim muncul dari komponen yang dipilih dan dikendalikan Kapitech bertentangan dengan scope, tanggung jawab dinilai berdasarkan contract dan hukum.\n\nPembedaan ini penting agar masalah proyek tidak otomatis dibebankan kepada satu pihak tanpa melihat siapa yang memberikan, memilih, mengontrol, atau menginstruksikan material terkait.' },
    { title: '43. Penghentian karena security atau aktivitas melawan hukum', body: 'Kapitech dapat mengambil langkah yang wajar jika permintaan proyek menimbulkan risiko security material, meminta aktivitas melawan hukum, melibatkan akses tidak sah, atau meminta tim melewati kontrol teknis atau legal. Langkah dapat berupa menolak request tertentu, mengisolasi environment, menunda deployment, meminta metode akses lebih aman, atau melakukan escalation ke contact klien yang berwenang.\n\nSecurity pause berbeda dari commercial pause. Tujuannya adalah mengurangi risiko langsung sambil tetap menyediakan jalur untuk melanjutkan pekerjaan yang sah bila memungkinkan.' },
    { title: '44. Sengketa tentang quality, scope, atau acceptance', body: 'Jika para pihak berbeda pendapat tentang apakah pekerjaan memenuhi kontrak, langkah pertama yang paling berguna adalah mengidentifikasi requirement, reference yang disetujui, bukti behaviour hasil kerja, dan gap yang tepat. Pernyataan bahwa proyek “terasa salah” dapat menjadi feedback, tetapi belum tentu cukup untuk menentukan non-conformance kontraktual.\n\nJika memungkinkan, defect harus dipisahkan dari change request, prioritas bisnis baru, perubahan konten, dan perubahan preferensi. Hal ini membantu menentukan remediation dengan lebih jelas dan mengurangi konflik yang tidak perlu.' },
    { title: '45. Kewajiban yang tetap berlaku dan close-out', body: 'Berakhirnya proyek tidak selalu mengakhiri seluruh kewajiban. Ketentuan tentang fee yang belum dibayar, IP rights yang telah diberikan, confidentiality, Personal Data, licence, indemnity, dispute resolution, liability, dan record dapat tetap berlaku sesuai isi atau sifatnya.\n\nPara pihak juga sebaiknya meninjau pencabutan akses, rotasi credential, pengembalian atau penghapusan data, source-code handover, domain ownership, hosting control, subscription ownership, dan kontrak pihak ketiga yang masih aktif sebagai bagian dari close-out.' }
  ]
};

export const TermsOfService = () => {
  const { language } = useLanguage();
  const current = language === 'id' ? sections.id : sections.en;
  const extra = language === 'id' ? supplemental.id : supplemental.en;
  const ordered = [...current.slice(0, -2), ...extra, ...current.slice(-2)];
  return (
    <PolicyPageShell
      eyebrow={language === 'id' ? 'Ketentuan Penggunaan & Layanan' : 'Service Terms & Conditions'}
      title={language === 'id' ? 'Syarat Layanan.' : 'Terms of Service.'}
      updated={language === 'id' ? 'Diperbarui: 8 Oktober 2026' : 'Updated: October 8, 2026'}
      summary={language === 'id'
        ? 'Dokumen ini menetapkan kerangka lengkap penggunaan website, pembentukan engagement, scope, perubahan pekerjaan, approval, pembayaran, intellectual property, confidentiality, security, third-party services, warranty, termination, liability, dan penyelesaian sengketa.'
        : 'This document sets out the full framework for website use, engagement formation, scope, changes, approvals, payment, intellectual property, confidentiality, security, third-party services, warranty, termination, liability, and disputes.'}
      sections={ordered}
    />
  );
};